class D:
    def __init__(self, x):
        self.x = x
    def __add__(self, o):
        return D(self.x + 1)
print((D(1) + D(2)).x)

class E:
    def __init__(self, x):
        self.x = x
    def __add__(self, o):
        return E(o.x + 1)
print((E(1) + E(2)).x)

class F:
    def __init__(self, x):
        self.x = x
    def __add__(self, o):
        return F(self.x * 10 + o.x)
print((F(1) + F(2)).x)
